import 'dart:io';

import 'config.dart';

const _begin =
    '// store_asset_packs: begin (generated; edit pubspec.yaml instead)';
const _end = '// store_asset_packs: end';
const _generatedHeader =
    '// Generated by `dart run store_asset_packs:android`. Edits are overwritten;\n'
    '// change the store_asset_packs: section of pubspec.yaml and run it again.';

/// Creates or refreshes the Play asset-pack modules and wires them into the
/// Gradle build (Kotlin DSL).
Future<void> runAndroid(ProjectConfig config, {bool check = false}) async {
  final android = config.androidDir;
  final settings = File('${android.path}/settings.gradle.kts');
  final app = File('${android.path}/app/build.gradle.kts');
  if (!settings.existsSync() || !app.existsSync()) {
    throw ToolException(
      'Expected ${settings.path} and ${app.path}. Only the '
      'Gradle Kotlin DSL (.kts) is supported.',
    );
  }
  requireSources(config.packs);

  final changes = <String>[];
  void write(File file, String content) {
    if (file.existsSync() && file.readAsStringSync() == content) return;
    changes.add(relativePath(file.path, config.root.path));
    if (!check) {
      file.parent.createSync(recursive: true);
      file.writeAsStringSync(content);
    }
  }

  for (final pack in config.packs) {
    final module = Directory('${android.path}/${pack.name}');
    final buildFile = File('${module.path}/build.gradle.kts');
    if (buildFile.existsSync() &&
        !buildFile.readAsStringSync().contains(_generatedHeader)) {
      throw ToolException(
        '${buildFile.path} exists and was not generated by '
        'store_asset_packs. Move it away or rename the pack.',
      );
    }
    write(buildFile, packBuildFile(pack, module, config.root));
    write(
      File('${module.path}/.gitignore'),
      '# Synced from ${relativePath(pack.source.path, config.root.path)} '
      'at build time.\n/src/main/assets/\n/build/\n',
    );
  }

  final includes = config.packs.map((p) => '":${p.name}"').join(', ');
  write(
    settings,
    replaceBlock(
      settings.readAsStringSync(),
      'include($includes)',
      after: RegExp(r'^include\(":app"\).*$', multiLine: true),
      indent: '',
    ),
  );
  write(
    app,
    replaceBlock(
      app.readAsStringSync(),
      'assetPacks += listOf($includes)',
      after: RegExp(r'^android\s*\{\s*$', multiLine: true),
      indent: '    ',
    ),
  );

  _warnStale(config);

  if (changes.isEmpty) {
    stdout.writeln('Android asset packs are up to date.');
  } else if (check) {
    stdout.writeln('Out of date: ${changes.join(', ')}');
    exitCode = 1;
  } else {
    stdout.writeln('Updated ${changes.join(', ')}');
  }
  for (final pack in config.packs) {
    stdout.writeln(
      '  ${pack.name}: ${pack.androidDeliveryType} ← '
      '${relativePath(pack.source.path, config.root.path)}',
    );
    if (pack.androidDeliveryType == 'install-time') {
      stdout.writeln(
        '    note: install-time packs are inside the APK, so '
        'StoreAssetPacks.getPackPath returns null for them.',
      );
    }
  }
}

/// The asset-pack module's build file. The pack's files stay in their source
/// folder; a Sync task copies them into the module's gitignored
/// `src/main/assets/<pack>/` before any of the module's tasks run. The plugin's
/// getPackPath returns that `<pack>` directory.
String packBuildFile(PackConfig pack, Directory module, Directory root) {
  final source = relativePath(pack.source.path, module.path);
  return '''
$_generatedHeader
plugins {
    id("com.android.asset-pack")
}

assetPack {
    packName.set("${pack.name}")
    dynamicDelivery {
        deliveryType.set("${pack.androidDeliveryType}")
    }
}

// The pack's files live in ${relativePath(pack.source.path, root.path)}/. Syncing them into the
// gitignored src/main/assets keeps a single copy in git. They go under
// ${pack.name}/ because Play needs every path to be unique across all packs.
val syncPackAssets = tasks.register<Sync>("syncPackAssets") {
    from(file("$source"))
    into(layout.projectDirectory.dir("src/main/assets/${pack.name}"))
}
tasks.configureEach {
    if (name != "syncPackAssets" && name != "clean") dependsOn(syncPackAssets)
}
''';
}

/// Replaces the marked block in [source] with [line], or inserts it after the
/// first match of [after].
String replaceBlock(
  String source,
  String line, {
  required RegExp after,
  required String indent,
}) {
  final block = '$indent$_begin\n$indent$line\n$indent$_end';
  final existing = RegExp(
    '^[ \\t]*${RegExp.escape(_begin)}\\n[\\s\\S]*?^[ \\t]*${RegExp.escape(_end)}',
    multiLine: true,
  );
  if (existing.hasMatch(source)) {
    return source.replaceFirst(existing, block);
  }
  final match = after.firstMatch(source);
  if (match == null) {
    throw ToolException(
      'Could not find where to add `$line` (looked for ${after.pattern}).',
    );
  }
  return '${source.substring(0, match.end)}\n$block${source.substring(match.end)}';
}

void _warnStale(ProjectConfig config) {
  for (final entity in config.androidDir.listSync()) {
    if (entity is! Directory) continue;
    final name = entity.path.split('/').last;
    final build = File('${entity.path}/build.gradle.kts');
    if (config.packs.any((p) => p.name == name) || !build.existsSync()) {
      continue;
    }
    if (build.readAsStringSync().contains(_generatedHeader)) {
      stdout.writeln(
        'warning: android/$name is a generated asset pack that '
        'is no longer configured; delete the folder if you no longer need it.',
      );
    }
  }
}
